#!/bin/bash
#---------------------------------------------------------------------------
# build.sh : B4's programs -> b4/work/<group>/<test>.elf
#
#   ./build.sh [group ...]      (default: all the groups below)
#
# riscv-arch-test (ACT4, $ARCH_TEST, default ~/RISCV/riscv-arch-test):
#   I M Zca Zba Zbb Zbc Zbs Zicond Zicsr Zifencei Zicntr  tests/rv64i/<group>
#   Sm Exceptions                                          generated by testgen
#   dir                                                    b4/dir: directed tests
# The privileged tests are not in the checkout: testgen writes them to
# work/gen (Python with rich and typer). Of those, the ones whose
# REQUIRED_EXTENSIONS fit the core (I, Sm, S, U, Zca, Zicntr, Zicsr) are
# built; the Interrupts tests are not (no interrupt source in Phase 1).
#
# Each test is built as the framework builds its signature ELF (-DSIGNATURE,
# the test's own -march), on act/: rvtest_config.h (the core's
# configuration, by hand), rvmodel_macros.h (HTIF), riscv_arch_test.h and
# act_sig_macros.h (sail_macros.h without Sail's CLINT), link.ld (the
# bench's 64 MB RAM). The expected values come from lock-step with Spike at
# every instruction, not from a Sail signature (Plan/CORE.md 5.7).
# b4/dir/*.S: illegal.S, the exceptions found at decode (FP instructions with
# mstatus.FS off, illegal compressed encodings and their tval, either slot).
# -mno-relax: binutils 2.43 picks how to fill a code alignment by the relax
# option at the end of the file, and the tests' .option pop sets it back
# there: LA's .p2align 5 (made under norelax) came out as zeros, not nops.
# The tests turn relaxation off anyway (the framework wants binutils 2.44).
#---------------------------------------------------------------------------
cd "$(dirname "$0")"
A=${ARCH_TEST:-$HOME/RISCV/riscv-arch-test}
CC=${CC:-/opt/riscv/bin/riscv64-unknown-elf-gcc}
PY=${PYTHON:-python3}
GROUPS_U="I M Zca Zba Zbb Zbc Zbs Zicond Zicsr Zifencei Zicntr"
GROUPS_P="Sm Exceptions"
[ $# -gt 0 ] && SEL="$*" || SEL="$GROUPS_U $GROUPS_P dir"
FIT=" I Sm S U Zca Zicntr Zicsr "         # the extensions a privileged test may require

if [[ " $SEL " =~ " Sm " || " $SEL " =~ " Exceptions " ]]; then
    mkdir -p work/gen
    G=$PWD/work/gen
    (cd $A && PYTHONPATH=generators/testgen/src $PY -c \
        "import sys; from testgen.cli import main; sys.argv=['testgen','testplans','-o','$G','-e','Sm,Exceptions','-j','0']; main()") \
        > work/gen.log 2>&1 || { cat work/gen.log; exit 1; }
fi

fits()      # the REQUIRED_EXTENSIONS line of a test: every entry (or one of a list) is in FIT
{
    local req=$(grep -m1 "REQUIRED_EXTENSIONS:" $1 | sed 's/.*: //')
    $PY -c "
import ast, sys
fit = set('$FIT'.split())
ok = all((set(e) & fit) if isinstance(e, list) else (e in fit) for e in ast.literal_eval(sys.argv[1]))
sys.exit(0 if ok else 1)" "$req"
}

n=0
for g in $SEL; do
    if [ $g = dir ]; then
        mkdir -p work/dir
        for s in dir/*.S; do
            $CC -nostdlib -nostartfiles -march=rv64gc -mabi=lp64 -T ../b2/link.ld $s -o work/dir/$(basename $s .S).elf || exit 1
            n=$((n + 1))
        done
        continue
    fi
    case " $GROUPS_P " in *" $g "*) D=work/gen/priv/$g ;; *) D=$A/tests/rv64i/$g ;; esac
    [ -d $D ] || { echo "build.sh: no $D"; exit 1; }
    mkdir -p work/$g
    for s in $D/*.S; do
        t=$(basename $s .S)
        case " $GROUPS_P " in *" $g "*) fits $s || continue ;; esac
        m=$(grep -m1 "# MARCH:" $s | sed 's/.*: //; s/\${XLEN}/64/')
        $CC -I act -I $A/tests/env -T act/link.ld -O0 -g -mcmodel=medany -nostdlib -mno-relax \
            -march=$m -mabi=lp64 -DSIGNATURE -DXLEN=64 -DTEST_FLEN=0 "-DTEST_FILE=\"$t\"" \
            -Wl,--defsym=__stack_size=128 $s -o work/$g/$t.elf || exit 1
        n=$((n + 1))
    done
done
echo "build.sh: $n programs"
